// API transversale des résumés, SLA et notifications internes.
using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using StbMonitoring.Application.Contracts;using StbMonitoring.Application.Interfaces;using StbMonitoring.Domain.Constants;
namespace StbMonitoring.Api.Controllers;
[ApiController,Authorize]public sealed class OperationsController(IOperationsService service):ControllerBase
{private Guid Actor()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet("api/operations/summary")]public async Task<IActionResult>Summary(CancellationToken ct)=>Ok(await service.SummaryAsync(Actor(),ct));[HttpGet("api/sla-policies"),Authorize(Policy=PermissionNames.SlaManage)]public async Task<IActionResult>Slas(CancellationToken ct)=>Ok(await service.SlasAsync(ct));[HttpPost("api/sla-policies"),Authorize(Policy=PermissionNames.SlaManage)]public async Task<IActionResult>CreateSla(SlaPolicyRequest r,CancellationToken ct)=>Ok(await service.CreateSlaAsync(r,ct));[HttpPut("api/sla-policies/{id:guid}"),Authorize(Policy=PermissionNames.SlaManage)]public async Task<IActionResult>UpdateSla(Guid id,SlaPolicyRequest r,CancellationToken ct)=>Ok(await service.UpdateSlaAsync(id,r,ct));[HttpPatch("api/sla-policies/{id:guid}/active"),Authorize(Policy=PermissionNames.SlaManage)]public async Task<IActionResult>SlaActive(Guid id,[FromQuery]bool value,CancellationToken ct){await service.SetSlaActiveAsync(id,value,ct);return NoContent();}[HttpGet("api/notifications"),Authorize(Policy=PermissionNames.NotificationsRead)]public async Task<IActionResult>Notifications(CancellationToken ct)=>Ok(await service.NotificationsAsync(Actor(),ct));[HttpPatch("api/notifications/{id:guid}/read"),Authorize(Policy=PermissionNames.NotificationsRead)]public async Task<IActionResult>Read(Guid id,CancellationToken ct){await service.ReadNotificationAsync(id,Actor(),ct);return NoContent();}[HttpPost("api/notifications/read-all"),Authorize(Policy=PermissionNames.NotificationsRead)]public async Task<IActionResult>ReadAll(CancellationToken ct){await service.ReadAllAsync(Actor(),ct);return NoContent();}}
